SELECT s0."rid_merge_mergetag" AS "$k0", s0."f_mergetag_created_at" AS "created_at", s0."f_mergetag_updated_at" AS "updated_at", s0."f_mergetag_property_id" AS "property_id", s0."f_mergetag_property_name" AS "property_name", s0."f_mergetag_can_delete" AS "can_delete" FROM "tbl_merge_mergetag" AS s0 WHERE s0."ref_mergetag_owner" = :_scope AND (s0."f_mergetag_property_id" = :property) ORDER BY s0."rid_merge_mergetag" ASC
